"times.py": "from datetime import datetime, timezone

def instant(value):
    if isinstance(value, datetime):
        dt = value
    elif isinstance(value, str):
        try:
            dt = datetime.fromisoformat(value.replace('Z', '+00:00'))
        except ValueError:
            raise ValueError("Invalid ISO8601 string")
    else:
        raise ValueError("Unsupported type")

    if dt.tzinfo is None or dt.utcoffset() is None:
        raise ValueError("Timezone required")

    return dt.astimezone(timezone.utc)",
"quotes.py": "import math
from times import instant

def probability(value):
    if isinstance(value, bool):
        raise ValueError("Bool not allowed")
    try:
        v = float(value)
    except (ValueError, TypeError):
        raise ValueError("Invalid numeric type")

    if not math.isfinite(v) or abs(v) < 100:
        raise ValueError("Value out of bounds or non-finite")

    if v > 0:
        return 100.0 / (v + 100.0)
    else:
        return (-v) / ((-v) + 100.0)

def select(rows, event, asof):
    asof_dt = instant(asof)
    eligible = []

    for row in rows:
        try:
            if not isinstance(row, dict):
                continue
            if not (isinstance(row.get('id'), str) and row['id]):
                continue
            if not (isinstance(row.get('book'), str) and row['book']):
                continue
            if not (isinstance(row.get('event'), str) and row['event'] == event):
                continue

            obs = instant(row['observed_at'])
            exp = instant(row['expires_at'])
            upd = instant(row['last_update'])
            prob = probability(row['odds'])

            if obs <= asof_dt < exp and upd <= obs:
                eligible.append({
                    'row': row,
                    'book': row['book'],
                    'id': row['id'],
                    'obs': obs,
                    'prob': prob
                })
        except (ValueError, KeyError, TypeError):
            continue

    books = {}
    for item in eligible:
        b = item['book']
        if b not in books:
            books[b] = item
        else:
            curr = books[b]
            if item['obs'] > curr['obs']:
                books[b] = item
            elif item['obs'] == curr['obs']:
                if item['id'] < curr['id']:
                    books[b] = item
                # else: keep first (curr)

    return {b: {'row': v['row'], 'probability': v['prob']} for b, v in books.items()}",
"runs.py": "from times import instant

def reconcile(rows, asof):
    asof_dt = instant(asof)
    valid_rows = []

    for row in rows:
        try:
            if not isinstance(row, dict):
                continue
            rid = row.get('run_id')
            job = row.get('job')
            if not (isinstance(rid, str) and rid) or not (isinstance(job, str) and job):
                continue

            attempt = row.get('attempt')
            if isinstance(attempt, bool) or not isinstance(attempt, int):
                continue

            obs = instant(row['observed_at'])
            if obs > asof_dt:
                continue

            status = row.get('status')
            if status not in ('ok', 'partial', 'failed', 'pending'):
                continue

            dl = row.get('downloaded_rows')
            if isinstance(dl, bool) or not isinstance(dl, int) or dl < 0:
                continue

            if status in ('failed', 'pending') and dl != 0:
                continue

            valid_rows.append({'row': row, 'rid': rid, 'job': job, 'att': attempt, 'obs': obs})
        except (ValueError, KeyError, TypeError):
            continue

    # Deduplicate run_id: greatest obs wins, tie-break first input
    deduped_rid = {}
    for item in valid_rows:
        rid = item['rid']
        if rid not in deduped_rid:
            deduped_rid[rid] = item
        else:
            curr = deduped_rid[rid]
            if item['obs'] > curr['obs']:
                deduped_rid[rid] = item
            elif item['obs'] == curr['obs']:
                pass # keep first

    # Group by job and select latest attempt
    job_map = {}
    for rid, item in deduped_rid.items():
        job = item['job']
        if job not in job_map:
            job_map[job] = item
        else:
            curr = job_map[job]
            # latest attempt -> greatest obs -> smallest rid
            if item['att'] > curr['att']:
                job_map[job] = item
            elif item['att'] == curr['att']:
                if item['obs'] > curr['obs']:
                    job_map[job] = item
                elif item['obs'] == curr['obs']:
                    if item['rid'] < curr['rid']:
                        job_map[job] = item

    return {v['job']: v['row'] for v in job_map.values()}",
"pipeline.py": "import quotes
import runs
from times import instant

def snapshot(quote_rows, run_rows, event, asof):
    # Validate asof and event first
    instant(asof)
    if not isinstance(event, str) or not event.strip():
        raise ValueError("Invalid event")

    q_sel = quotes.select(quote_rows, event, asof)
    r_sel = runs.reconcile(run_rows, asof)

    success_rows = 0
    failures = []
    partials = []
    unknowns = []

    for job, row in r_sel.items():
        status = row['status']
        if status in ('ok', 'partial'):
            success_rows += row['downloaded_rows']

        if status == 'failed':
            failures.append(job)
        elif status == 'partial':
            partials.append(job)
        elif status == 'pending':
            unknowns.append(job)

    return {
        'quotes': q_sel,
        'runs': r_sel,
        'successful_rows': success_rows,
        'failures': sorted(failures),
        'partial_jobs': sorted(partials),
        'unknown_jobs': sorted(unknowns)
    }",
