import math
import copy

def run_tests(candidate):
    # 1. Validation Tests
    try:
        candidate([], [], "", datetime.datetime.now(datetime.timezone.utc))
        raise AssertionError("Should fail on empty event")
    except ValueError:
        pass

    try:
        candidate([], [], "e", "not-a-date")
        raise AssertionError("Should fail on invalid asof")
    except ValueError:
        pass

    # 2. Quotes Tests
    asof = datetime.datetime(2023, 1, 1, 12, 0, tzinfo=datetime.timezone.utc)
    q_rows = [
        {'id': '1', 'book': 'B1', 'event': 'E1', 'observed_at': '2023-01-01T11:00:00Z', 'expires_at': '2023-01-01T13:00:00Z', 'last_update': '2023-01-01T11:00:00Z', 'odds': 100},
        {'id': '2', 'book': 'B1', 'event': 'E1', 'observed_at': '2023-01-01T11:30:00Z', 'expires_at': '2023-01-01T13:00:00Z', 'last_update': '2023-01-01T11:30:00Z', 'odds': 200},
        {'id': '3', 'book': 'B1', 'event': 'E1', 'observed_at': '2023-01-01T11:30:00Z', 'expires_at': '2023-01-01T13:00:00Z', 'last_update': '2023-01-01T11:30:00Z', 'odds': 300}, # Tie id
        {'id': '4', 'book': 'B1', 'event': 'E1', 'observed_at': '2023-01-01T14:00:00Z', 'expires_at': '2023-01-01T15:00:00Z', 'last_update': '2023-01-01T14:00:00Z', 'odds': 100}, # Future
    ]
    res = candidate(q_rows, [], "E1", asof)
    assert res['quotes']['B1']['probability'] == 100.0 / (200.0 + 100.0)
    assert res['quotes']['B1']['row']['id'] == '2'

    # 3. Runs Tests
    r_rows = [
        {'run_id': 'r1', 'job': 'j1', 'attempt': 1, 'observed_at': '2023-01-01T10:00:00Z', 'status': 'ok', 'downloaded_rows': 10},
        {'run_id': 'r1', 'job': 'j1', 'attempt': 2, 'observed_at': '2023-01-01T11:00:00Z', 'status': 'failed', 'downloaded_rows': 0},
        {'run_id': 'r2', 'job': 'j2', 'attempt': 1, 'observed_at': '2023-01-01T10:00:00Z', 'status': 'partial', 'downloaded_rows': 5},
        {'run_id': 'r3', 'job': 'j3', 'attempt': 1, 'observed_at': '2023-01-01T10:00:00Z', 'status': 'pending', 'downloaded_rows': 0},
    ]
    res = candidate([], r_rows, "E1", asof)
    assert res['successful_rows'] == 5
    assert 'j1' in res['failures']
    assert 'j2' in res['partial_jobs']
    assert 'j3' in res['unknown_jobs']
    assert res['runs']['j1']['status'] == 'failed'

    # 4. Complex Tie-breaking
    r_rows_tie = [
        {'run_id': 'r1', 'job': 'j1', 'attempt': 1, 'observed_at': '2023-01-01T10:00:00Z', 'status': 'ok', 'downloaded_rows': 10},
        {'run_id': 'r1', 'job': 'j1', 'attempt': 1, 'observed_at': '2023-01-01T10:00:00Z', 'status': 'ok', 'downloaded_rows': 20}, # Duplicate
    ]
    res = candidate([], r_rows_tie, "E1", asof)
    assert res['successful_rows'] == 10 # First input rule

    print("All tests passed")"
